  "q": "Which of the following is an essential practice in Software Quality Assurance to ensure that software meets predefined standards and requirements?",
  "opts": {
   "A": "Code reviews",
   "B": "Load testing",
   "C": "Exploratory testing",
   "D": "Mutation testing"
  },
  "ans": "A",
