  "exp": "In Cisco NAT configuration, the interface-level command \"ip nat inside\" is applied to the interface that connects to the private (inside) network, while \"ip nat outside\" is applied to the interface facing the public (outside) network such as the internet. \"ip outside global\" and \"ip inside local\" are not valid Cisco commands at all — inside local/global and outside local/global are merely the four NAT address-type terms, not command syntax. Since the question asks specifically about the private-network-facing interface, the correct command is (a) ip nat inside.",
