  "no": 11,
  "paper": "TECH1",
  "unit": "1",
  "sub": "IOS and Security Device Manager",
  "q": "Which command loads a new version of the Cisco IOS into a router?",
  "opts": {
   "A": "copy flash ftp",
   "B": "copy ftp flash",
   "C": "copy flash tftp",
   "D": "copy tftp flash"
  },
  "ans": "D",
  "exp": "Cisco's copy command syntax is \"copy <source> <destination>\", so to load a new IOS image FROM a TFTP server INTO the router's flash memory, the command is \"copy tftp flash\". Option (a) \"copy flash ftp\" and (c) \"copy flash tftp\" both go the wrong direction — they back up the existing IOS image out of flash onto a server, rather than loading a new one in. Option (b) \"copy ftp flash\" uses FTP rather than the standard TFTP file-transfer method typically used for IOS upgrades in this exam context, making (d) the intended answer.",
