  "sub": "SDLC Methodologies: Spiral model",
  "q": "Staff turnover, poor communication with the customer are risks that are extrapolated from past experience are called __________.",
  "opts": {
   "A": "Business risks",
   "B": "Predictable risks",
   "C": "Project risks",
   "D": "Technical risks"
  },
  "ans": "B",
  "exp": "Software risk taxonomies (e.g., Pressman) classify risks as known risks (documented facts, e.g. a fixed deadline), predictable risks (extrapolated from past project experience, e.g. staff turnover, poor customer communication, staff attrition), and unpredictable risks (rare, hard-to-foresee events). The question's own wording -- 'risks extrapolated from past experience' -- is essentially the textbook definition of predictable risks, so (b) matches directly. Project risks and technical risks are separate classification axes (by impact area: budget/schedule vs. design/implementation), not by how the risk was identified, so they don't fit the 'extrapolated from past experience' criterion as precisely.",
  "prov": "Two independent solvers agreed (no official key for this sitting)",
