  "q": "Which of these access specifiers can be used for an interface?",
  "opts": {
   "A": "public",
   "B": "protected",
   "C": "private",
   "D": "All of the mentioned"
  },
  "ans": "A",
  "exp": "A top-level Java interface, like a top-level class, may only be declared public or left with default (package-private) access; protected and private are illegal modifiers for a top-level type declaration since they only make sense relative to an enclosing class or member. So among the listed options, only 'public' is a valid access specifier for a top-level interface declaration, making 'All of the mentioned' incorrect. (Nested member interfaces since Java 9 can additionally be private, but that narrower case is not what this question is testing.)",
  "prov": "Two independent solvers agreed (no official key for this sitting)",
