  "sub": "OOPS and Core Java",
  "q": "Which component is used to compile, debug and execute java program?",
  "opts": {
   "A": "JVM",
   "B": "JDK",
   "C": "JIT",
   "D": "JRE"
  },
  "ans": "B",
  "exp": "The Java Development Kit (JDK) is the full toolset for developers: it bundles the javac compiler, a debugger (jdb), and a JRE to run programs, so it alone covers compile, debug AND execute. The JVM is only the runtime engine that executes bytecode, the JRE is the runtime environment (JVM plus libraries) needed only to run programs, and the JIT is a runtime-optimization component inside the JVM - none of these three alone provide compilation and debugging tools.",
  "prov": "Two independent solvers agreed (no official key for this sitting)",
