  "sub": "Servlet and JSP",
  "q": "Which one is the correct order of phases in JSP life cycle?",
  "opts": {
   "A": "Initialization, Cleanup, Compilation, Execution",
   "B": "Initialization, Compilation, Cleanup, Execution",
   "C": "Compilation, Initialization, Execution, Cleanup",
   "D": "Cleanup, Compilation, Initialization, Execution"
  },
  "ans": "C",
  "exp": "A JSP page is first translated and compiled into a servlet class (Compilation), then jspInit() runs once to set up resources (Initialization), then _jspService() handles each incoming request (Execution), and finally jspDestroy() releases resources when the page is retired (Cleanup). Any option placing Initialization or Cleanup before Compilation, or Cleanup before Execution, is impossible since nothing exists yet at that point to initialize or clean up.",
