  "unit": "4",
  "sub": "OOPS and Core Java",
  "q": "Which of these data types is used by operating system to manage the Recursion in Java?",
  "opts": {
   "A": "Array",
   "B": "Stack",
   "C": "Queue",
   "D": "Tree"
  },
  "ans": "B",
  "exp": "Each recursive method call pushes a new stack frame (holding local variables, parameters and the return address) onto the thread's call stack, and returning from the call pops that frame off - a strict last-in-first-out discipline that exactly matches how nested calls return. Arrays, queues and trees are not the structure the JVM/OS uses under the hood to track nested method invocations, so they do not fit how recursion is actually implemented.",
  "prov": "Two independent solvers agreed (no official key for this sitting)",
  "note": ""
