  "sub": "Data Warehousing",
  "q": "Data warehouse is:",
  "opts": {
   "A": "The actual discovery phase of a knowledge discovery process",
   "B": "The stage of selecting the right data for a KDD process",
   "C": "A subject-oriented integrated time variant non-volatile collection of data in support of management",
   "D": "None of these"
  },
  "ans": "C",
  "exp": "This is Bill Inmon's classic definition of a data warehouse: it is subject-oriented (organized around business subjects, not applications), integrated (consolidated from multiple sources into a consistent format), time-variant (holds historical data over time), and non-volatile (loaded and read, not routinely updated/deleted) - all in support of management's decision-making. Options (a) and (b) instead describe steps within the broader Knowledge Discovery in Databases (KDD) process, of which data warehousing is a supporting infrastructure, not a synonym.",
  "prov": "Two independent solvers agreed (no official key for this sitting)",
